#include "analysis/Checks.h"

namespace mm::analysis
{
namespace
{
juce::String signedDb (double v, int decimals = 1)
{
    const auto s = juce::String (std::abs (v), decimals);
    return (v < 0.0 && std::abs (v) >= 0.5 * std::pow (10.0, -decimals) ? juce::String (juce::CharPointer_UTF8 ("\xe2\x88\x92"))
                                                                         : juce::String ("+"))
         + s;
}

juce::String minus (double v, int decimals = 1)
{
    const auto s = juce::String (std::abs (v), decimals);
    return (v < -0.5 * std::pow (10.0, -decimals) ? juce::String (juce::CharPointer_UTF8 ("\xe2\x88\x92")) : juce::String()) + s;
}

juce::String ru (const char* utf8) { return juce::String (juce::CharPointer_UTF8 (utf8)); }

Light byAbs (double v, double g, double y) { return std::abs (v) <= g ? Light::ok : (std::abs (v) <= y ? Light::warn : Light::bad); }
} // namespace

const char* tonalBandName (int band)
{
    static const char* names[] = { "Sub", "Bass", "Low-mid", "Mid", "Presence", "Air" };
    return names[std::clamp (band, 0, numTonalBands - 1)];
}

const char* tonalBandRange (int band)
{
    static const char* ranges[] = { "20\xe2\x80\x93" "60 Hz", "60\xe2\x80\x93" "150 Hz", "150\xe2\x80\x93" "500 Hz",
                                    "0.5\xe2\x80\x93" "2 kHz", "2\xe2\x80\x93" "6 kHz", "6\xe2\x80\x93" "16 kHz" };
    return ranges[std::clamp (band, 0, numTonalBands - 1)];
}

juce::String tonalLabel (int band, double deviation)
{
    return juce::String (tonalBandName (band)) + " " + signedDb (deviation) + " dB vs target";
}

std::vector<Check> computeChecks (const CheckInput& in, const Targets& t, const Thresholds& th)
{
    std::vector<Check> out;

    // Six tonal bands
    static const char* advice[numTonalBands][2] = {
        { "\xd0\xa1\xd0\xb0\xd0\xbc\xd0\xb0\xd1\x8f \xd0\xbd\xd0\xb8\xd0\xb7\xd0\xba\xd0\xb0\xd1\x8f \xd0\xbe\xd0\xba\xd1\x82\xd0\xb0\xd0\xb2\xd0\xb0 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x92 \xd0\xbc\xd0\xb0\xd1\x88\xd0\xb8\xd0\xbd\xd0\xb5 \xd0\xb8 \xd0\xb2 \xd0\xba\xd0\xbb\xd1\x83\xd0\xb1\xd0\xb5 \xd0\xbd\xd0\xb8\xd0\xb7 \xd0\xb1\xd1\x83\xd0\xb4\xd0\xb5\xd1\x82 \xd0\xb3\xd1\x83\xd0\xb4\xd0\xb5\xd1\x82\xd1\x8c, \xd0\xb0 \xd0\xbb\xd0\xb8\xd0\xbc\xd0\xb8\xd1\x82\xd0\xb5\xd1\x80 \xd1\x80\xd0\xb0\xd0\xb1\xd0\xbe\xd1\x82\xd0\xb0\xd0\xb5\xd1\x82 \xd1\x81\xd0\xb8\xd0\xbb\xd1\x8c\xd0\xbd\xd0\xb5\xd0\xb5. \xd0\x9f\xd1\x80\xd0\xbe\xd0\xb2\xd0\xb5\xd1\x80\xd1\x8c\xd1\x82\xd0\xb5 \xd0\xb1\xd0\xbe\xd1\x87\xd0\xba\xd1\x83 \xd0\xb8 \xd0\xbd\xd0\xb8\xd0\xb6\xd0\xbd\xd0\xb8\xd0\xb5 \xd0\xbd\xd0\xbe\xd1\x82\xd1\x8b \xd0\xbd\xd0\xb0 \xd0\xb2\xd0\xba\xd0\xbb\xd0\xb0\xd0\xb4\xd0\xba\xd0\xb5 Low-End.",
          "\xd0\xa1\xd0\xb0\xd0\xbc\xd0\xb0\xd1\x8f \xd0\xbd\xd0\xb8\xd0\xb7\xd0\xba\xd0\xb0\xd1\x8f \xd0\xbe\xd0\xba\xd1\x82\xd0\xb0\xd0\xb2\xd0\xb0 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x9d\xd0\xb0 \xd0\xb1\xd0\xbe\xd0\xbb\xd1\x8c\xd1\x88\xd0\xb8\xd1\x85 \xd1\x81\xd0\xb8\xd1\x81\xd1\x82\xd0\xb5\xd0\xbc\xd0\xb0\xd1\x85 \xd1\x82\xd1\x80\xd0\xb5\xd0\xba \xd0\xb7\xd0\xb2\xd1\x83\xd1\x87\xd0\xb8\xd1\x82 \xd1\x82\xd0\xbe\xd0\xbd\xd0\xba\xd0\xbe. \xd0\x9f\xd1\x80\xd0\xbe\xd0\xb2\xd0\xb5\xd1\x80\xd1\x8c\xd1\x82\xd0\xb5 \xd0\xbd\xd0\xb0\xd1\x81\xd1\x82\xd1\x80\xd0\xbe\xd0\xb9\xd0\xba\xd1\x83 Subsonic \xd0\xb8 \xd0\xb1\xd0\xbe\xd1\x87\xd0\xba\xd1\x83." },
        { "\xd0\x91\xd0\xb0\xd1\x81\xd0\xbe\xd0\xb2\xd0\xb0\xd1\x8f \xd0\xbf\xd0\xbe\xd0\xbb\xd0\xbe\xd1\x81\xd0\xb0 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x91\xd0\xbe\xd1\x87\xd0\xba\xd0\xb0 \xd0\xb8 \xd0\xb1\xd0\xb0\xd1\x81 \xd0\xbc\xd0\xbe\xd0\xb3\xd1\x83\xd1\x82 \xd0\xb7\xd0\xb0\xd0\xbc\xd0\xb0\xd1\x81\xd0\xba\xd0\xb8\xd1\x80\xd0\xbe\xd0\xb2\xd0\xb0\xd1\x82\xd1\x8c \xd0\xb3\xd0\xb8\xd1\x82\xd0\xb0\xd1\x80\xd1\x8b.",
          "\xd0\x91\xd0\xb0\xd1\x81\xd0\xbe\xd0\xb2\xd0\xb0\xd1\x8f \xd0\xbf\xd0\xbe\xd0\xbb\xd0\xbe\xd1\x81\xd0\xb0 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x9c\xd0\xb8\xd0\xba\xd1\x81 \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd0\xb7\xd0\xb2\xd1\x83\xd1\x87\xd0\xb0\xd1\x82\xd1\x8c \xd1\x82\xd0\xbe\xd0\xbd\xd0\xba\xd0\xbe." },
        { "\xc2\xab\xd0\x93\xd1\x80\xd1\x8f\xd0\xb7\xd1\x8c\xc2\xbb 150\xe2\x80\x93" "500 Hz \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x97\xd0\xb2\xd1\x83\xd0\xba \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd0\xb1\xd1\x8b\xd1\x82\xd1\x8c \xd0\xbc\xd1\x83\xd1\x82\xd0\xbd\xd1\x8b\xd0\xbc. \xd0\x9f\xd0\xbe\xd0\xbf\xd1\x80\xd0\xbe\xd0\xb1\xd1\x83\xd0\xb9\xd1\x82\xd0\xb5 \xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0\xd0\xbc\xd0\xb8\xd1\x87\xd0\xb5\xd1\x81\xd0\xba\xd1\x83\xd1\x8e \xd0\xbf\xd0\xbe\xd0\xbb\xd0\xbe\xd1\x81\xd1\x83 EQ.",
          "\xd0\x9d\xd0\xb8\xd0\xb6\xd0\xbd\xd1\x8f\xd1\x8f \xd1\x81\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x93\xd0\xb8\xd1\x82\xd0\xb0\xd1\x80\xd1\x8b \xd0\xbc\xd0\xbe\xd0\xb3\xd1\x83\xd1\x82 \xd0\xb7\xd0\xb2\xd1\x83\xd1\x87\xd0\xb0\xd1\x82\xd1\x8c \xd1\x82\xd0\xbe\xd0\xbd\xd0\xba\xd0\xbe." },
        { "\xd0\xa1\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x97\xd0\xb2\xd1\x83\xd0\xba \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd0\xb1\xd1\x8b\xd1\x82\xd1\x8c \xc2\xab\xd0\xba\xd0\xbe\xd1\x80\xd0\xbe\xd0\xb1\xd0\xbe\xd1\x87\xd0\xbd\xd1\x8b\xd0\xbc\xc2\xbb.",
          "\xd0\xa1\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x92\xd0\xbe\xd0\xba\xd0\xb0\xd0\xbb \xd0\xb8 \xd0\xb3\xd0\xb8\xd1\x82\xd0\xb0\xd1\x80\xd1\x8b \xd0\xbc\xd0\xbe\xd0\xb3\xd1\x83\xd1\x82 \xd0\xbf\xd1\x80\xd0\xbe\xd0\xbf\xd0\xb0\xd0\xb4\xd0\xb0\xd1\x82\xd1\x8c." },
        { "\xd0\x92\xd0\xb5\xd1\x80\xd1\x85\xd0\xbd\xd1\x8f\xd1\x8f \xd1\x81\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x97\xd0\xb2\xd1\x83\xd0\xba \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd1\x83\xd1\x82\xd0\xbe\xd0\xbc\xd0\xbb\xd1\x8f\xd1\x82\xd1\x8c.",
          "\xd0\x92\xd0\xb5\xd1\x80\xd1\x85\xd0\xbd\xd1\x8f\xd1\x8f \xd1\x81\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x9c\xd0\xb8\xd0\xba\xd1\x81 \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd0\xb7\xd0\xb2\xd1\x83\xd1\x87\xd0\xb0\xd1\x82\xd1\x8c \xd0\xb3\xd0\xbb\xd1\x83\xd1\x85\xd0\xbe." },
        { "\xd0\x92\xd0\xb5\xd1\x80\xd1\x85 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\xa2\xd0\xb0\xd1\x80\xd0\xb5\xd0\xbb\xd0\xba\xd0\xb8 \xd0\xb8 \xc2\xab\xd0\xbf\xd0\xb5\xd1\x81\xd0\xbe\xd0\xba\xc2\xbb \xd0\xb3\xd0\xb8\xd1\x82\xd0\xb0\xd1\x80 \xd0\xbc\xd0\xbe\xd0\xb3\xd1\x83\xd1\x82 \xd1\x80\xd0\xb5\xd0\xb7\xd0\xb0\xd1\x82\xd1\x8c \xd1\x81\xd0\xbb\xd1\x83\xd1\x85.",
          "\xd0\x92\xd0\xb5\xd1\x80\xd1\x85 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8. \xd0\x9c\xd0\xb8\xd0\xba\xd1\x81 \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd0\xb7\xd0\xb2\xd1\x83\xd1\x87\xd0\xb0\xd1\x82\xd1\x8c \xd1\x82\xd1\x83\xd1\x81\xd0\xba\xd0\xbb\xd0\xbe." },
    };

    for (int b = 0; b < numTonalBands; ++b)
    {
        const double dev = in.tonal[(size_t) b] - t.tonal[(size_t) b];
        Check c;
        c.light = in.hasSignal ? byAbs (dev, th.tonalGreen, th.tonalYellow) : Light::info;
        c.title = tonalBandName (b);
        c.value = signedDb (dev) + " dB";
        c.detail = std::abs (dev) <= th.tonalGreen ? "Within target" : (dev > 0 ? "Above target" : "Below target");
        c.tooltip = tonalLabel (b, dev) + "\n"
                  + (std::abs (dev) <= th.tonalGreen ? ru ("\xd0\x9f\xd0\xbe\xd0\xbb\xd0\xbe\xd1\x81\xd0\xb0 \xd0\xb2 \xd0\xbd\xd0\xbe\xd1\x80\xd0\xbc\xd0\xb5. \xd0\x98\xd0\xb7\xd0\xbc\xd0\xb5\xd0\xbd\xd0\xb5\xd0\xbd\xd0\xb8\xd0\xb9 \xd0\xbd\xd0\xb5 \xd0\xbd\xd1\x83\xd0\xb6\xd0\xbd\xd0\xbe.")
                                                     : ru (advice[b][dev > 0 ? 0 : 1]));
        out.push_back (c);
    }

    // Mono loss
    {
        Check c;
        c.title = "Mono loss";
        c.value = minus (in.monoLossDb) + " dB";
        c.light = in.monoLossDb >= th.monoLossGreen ? Light::ok : (in.monoLossDb >= th.monoLossYellow ? Light::warn : Light::bad);
        c.detail = c.light == Light::ok ? "Safe on mono phones" : "Phase problems in mono";
        c.tooltip = ru ("\xd0\x9f\xd0\xbe\xd1\x82\xd0\xb5\xd1\x80\xd1\x8f \xd1\x83\xd1\x80\xd0\xbe\xd0\xb2\xd0\xbd\xd1\x8f, \xd0\xba\xd0\xbe\xd0\xb3\xd0\xb4\xd0\xb0 \xd1\x81\xd1\x82\xd0\xb5\xd1\x80\xd0\xb5\xd0\xbe \xd1\x81\xd0\xb2\xd0\xbe\xd0\xb4\xd0\xb8\xd1\x82\xd1\x81\xd1\x8f \xd0\xb2 \xd0\xbc\xd0\xbe\xd0\xbd\xd0\xbe. \xd0\x91\xd0\xbe\xd0\xbb\xd1\x8c\xd1\x88\xd0\xb0\xd1\x8f \xd0\xbf\xd0\xbe\xd1\x82\xd0\xb5\xd1\x80\xd1\x8f \xd0\xbe\xd0\xb7\xd0\xbd\xd0\xb0\xd1\x87\xd0\xb0\xd0\xb5\xd1\x82, \xd1\x87\xd1\x82\xd0\xbe \xd1\x87\xd0\xb0\xd1\x81\xd1\x82\xd1\x8c \xd0\xb7\xd0\xb2\xd1\x83\xd0\xba\xd0\xb0 \xd0\xbf\xd1\x80\xd0\xbe\xd0\xbf\xd0\xb0\xd0\xb4\xd1\x91\xd1\x82 \xd0\xbd\xd0\xb0 \xd1\x82\xd0\xb5\xd0\xbb\xd0\xb5\xd1\x84\xd0\xbe\xd0\xbd\xd0\xb5 \xd0\xb8 \xd0\xb2 \xd0\xba\xd0\xbb\xd1\x83\xd0\xb1\xd0\xb5. \xd0\xa1\xd0\xbc\xd0\xbe\xd1\x82\xd1\x80\xd0\xb8\xd1\x82\xd0\xb5 \xd0\xb2\xd0\xba\xd0\xbb\xd0\xb0\xd0\xb4\xd0\xba\xd1\x83 Stereo.");
        out.push_back (c);
    }

    // Low-band correlation
    {
        Check c;
        c.title = "Low-band corr.";
        c.value = minus (in.lowCorrelation, 2);
        c.light = in.lowCorrelation >= th.lowCorrGreen ? Light::ok : (in.lowCorrelation >= th.lowCorrYellow ? Light::warn : Light::bad);
        c.detail = c.light == Light::ok ? "Bass is mono-safe" : "Bass is not mono-safe";
        c.tooltip = ru ("\xd0\x9a\xd0\xbe\xd1\x80\xd1\x80\xd0\xb5\xd0\xbb\xd1\x8f\xd1\x86\xd0\xb8\xd1\x8f \xd0\xbd\xd0\xb8\xd0\xb7\xd0\xb0 \xd0\xbf\xd0\xbe\xd0\xba\xd0\xb0\xd0\xb7\xd1\x8b\xd0\xb2\xd0\xb0\xd0\xb5\xd1\x82, \xd0\xbd\xd0\xb0\xd1\x81\xd0\xba\xd0\xbe\xd0\xbb\xd1\x8c\xd0\xba\xd0\xbe \xd0\xbf\xd0\xbe\xd1\x85\xd0\xbe\xd0\xb6\xd0\xb8 \xd0\xbb\xd0\xb5\xd0\xb2\xd1\x8b\xd0\xb9 \xd0\xb8 \xd0\xbf\xd1\x80\xd0\xb0\xd0\xb2\xd1\x8b\xd0\xb9 \xd0\xba\xd0\xb0\xd0\xbd\xd0\xb0\xd0\xbb\xd1\x8b \xd0\xbd\xd0\xb8\xd0\xb6\xd0\xb5 \xd1\x87\xd0\xb0\xd1\x81\xd1\x82\xd0\xbe\xd1\x82\xd1\x8b Mono. 1 \xe2\x80\x94 \xd0\xbf\xd0\xbe\xd0\xbb\xd0\xbd\xd0\xbe\xd0\xb5 \xd0\xbc\xd0\xbe\xd0\xbd\xd0\xbe. \xd0\x95\xd1\x81\xd0\xbb\xd0\xb8 \xd0\xb7\xd0\xbd\xd0\xb0\xd1\x87\xd0\xb5\xd0\xbd\xd0\xb8\xd0\xb5 \xd0\xbd\xd0\xb8\xd0\xb7\xd0\xba\xd0\xbe\xd0\xb5, \xd0\xb2\xd0\xba\xd0\xbb\xd1\x8e\xd1\x87\xd0\xb8\xd1\x82\xd0\xb5 Mono \xd0\xb2 \xd0\xbc\xd0\xbe\xd0\xb4\xd1\x83\xd0\xbb\xd0\xb5 Low-End.");
        out.push_back (c);
    }

    // PLR
    {
        Check c;
        c.title = "PLR";
        c.value = juce::String (in.plr, 1) + " LU";
        c.light = in.plr >= th.plrGreen ? Light::ok : (in.plr >= th.plrYellow ? Light::warn : Light::bad);
        c.detail = c.light == Light::ok ? "Healthy dynamics" : (c.light == Light::warn ? "Dense, check the drums" : "Over-compressed");
        c.tooltip = ru ("PLR \xe2\x80\x94 \xd1\x80\xd0\xb0\xd0\xb7\xd0\xbd\xd0\xb8\xd1\x86\xd0\xb0 \xd0\xbc\xd0\xb5\xd0\xb6\xd0\xb4\xd1\x83 \xd0\xbf\xd0\xb8\xd0\xba\xd0\xbe\xd0\xbc \xd0\xb8 \xd1\x81\xd1\x80\xd0\xb5\xd0\xb4\xd0\xbd\xd0\xb5\xd0\xb9 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd0\xba\xd0\xbe\xd1\x81\xd1\x82\xd1\x8c\xd1\x8e. \xd0\x9c\xd0\xb0\xd0\xbb\xd0\xbe\xd0\xb5 \xd0\xb7\xd0\xbd\xd0\xb0\xd1\x87\xd0\xb5\xd0\xbd\xd0\xb8\xd0\xb5 \xd0\xbe\xd0\xb7\xd0\xbd\xd0\xb0\xd1\x87\xd0\xb0\xd0\xb5\xd1\x82, \xd1\x87\xd1\x82\xd0\xbe \xd1\x83\xd0\xb4\xd0\xb0\xd1\x80\xd1\x8b \xd0\xb1\xd0\xb0\xd1\x80\xd0\xb0\xd0\xb1\xd0\xb0\xd0\xbd\xd0\xbe\xd0\xb2 \xd1\x81\xd0\xbf\xd0\xbb\xd1\x8e\xd1\x89\xd0\xb5\xd0\xbd\xd1\x8b. \xd0\x9f\xd1\x80\xd0\xbe\xd0\xb2\xd0\xb5\xd1\x80\xd1\x8c\xd1\x82\xd0\xb5 Drive \xd0\xbb\xd0\xb8\xd0\xbc\xd0\xb8\xd1\x82\xd0\xb5\xd1\x80\xd0\xb0 \xd0\xb8 \xd0\xba\xd0\xbb\xd0\xb8\xd0\xbf\xd0\xbf\xd0\xb5\xd1\x80.");
        out.push_back (c);
    }

    // Harshness
    {
        const double dev = in.harshness - t.harshness;
        Check c;
        c.title = "Harshness";
        c.value = signedDb (dev) + " dB";
        c.light = in.hasSignal ? (dev <= th.harshGreen ? Light::ok : (dev <= th.harshYellow ? Light::warn : Light::bad)) : Light::info;
        c.detail = ru (dev <= th.harshGreen ? "3\xe2\x80\x93" "8 kHz in range" : "3\xe2\x80\x93" "8 kHz fizz above target");
        c.tooltip = ru ("\xd0\x96\xd1\x91\xd1\x81\xd1\x82\xd0\xba\xd0\xbe\xd1\x81\xd1\x82\xd1\x8c \xe2\x80\x94 \xd1\x8d\xd0\xbd\xd0\xb5\xd1\x80\xd0\xb3\xd0\xb8\xd1\x8f 3\xe2\x80\x93" "8 kHz \xd0\xbe\xd1\x82\xd0\xbd\xd0\xbe\xd1\x81\xd0\xb8\xd1\x82\xd0\xb5\xd0\xbb\xd1\x8c\xd0\xbd\xd0\xbe 0.5\xe2\x80\x93" "2 kHz. \xd0\x92\xd1\x8b\xd1\x81\xd0\xbe\xd0\xba\xd0\xbe\xd0\xb5 \xd0\xb7\xd0\xbd\xd0\xb0\xd1\x87\xd0\xb5\xd0\xbd\xd0\xb8\xd0\xb5 \xd0\xbe\xd0\xb7\xd0\xbd\xd0\xb0\xd1\x87\xd0\xb0\xd0\xb5\xd1\x82 \xc2\xab\xd0\xbf\xd0\xb5\xd1\x81\xd0\xbe\xd0\xba\xc2\xbb \xd0\xb3\xd0\xb8\xd1\x82\xd0\xb0\xd1\x80 \xd0\xb8 \xd1\x80\xd0\xb5\xd0\xb7\xd0\xba\xd0\xb8\xd0\xb5 \xd1\x82\xd0\xb0\xd1\x80\xd0\xb5\xd0\xbb\xd0\xba\xd0\xb8. \xd0\x9d\xd0\xb0 \xd0\xbd\xd0\xb0\xd1\x83\xd1\x88\xd0\xbd\xd0\xb8\xd0\xba\xd0\xb0\xd1\x85 DT 990 \xd1\x8d\xd1\x82\xd0\xbe \xd0\xbf\xd0\xbb\xd0\xbe\xd1\x85\xd0\xbe \xd1\x81\xd0\xbb\xd1\x8b\xd1\x88\xd0\xbd\xd0\xbe. \xd0\x9f\xd0\xbe\xd0\xbf\xd1\x80\xd0\xbe\xd0\xb1\xd1\x83\xd0\xb9\xd1\x82\xd0\xb5 \xd0\xb4\xd0\xb8\xd0\xbd\xd0\xb0\xd0\xbc\xd0\xb8\xd1\x87\xd0\xb5\xd1\x81\xd0\xba\xd1\x83\xd1\x8e \xd0\xbf\xd0\xbe\xd0\xbb\xd0\xbe\xd1\x81\xd1\x83 EQ \xd0\xbd\xd0\xb0 4\xe2\x80\x93" "8 kHz.");
        out.push_back (c);
    }

    // True peak vs ceiling
    {
        Check c;
        c.title = "True peak";
        c.value = minus (in.truePeak) + " dBTP";
        const double over = in.truePeak - t.truePeakCeiling;
        c.light = over <= 0.0 ? Light::ok : (over <= th.tpYellowMargin ? Light::warn : Light::bad);
        c.detail = over <= 0.0 ? "Below ceiling " + minus (t.truePeakCeiling) : "Above ceiling " + minus (t.truePeakCeiling);
        c.tooltip = ru ("True peak \xe2\x80\x94 \xd1\x80\xd0\xb5\xd0\xb0\xd0\xbb\xd1\x8c\xd0\xbd\xd1\x8b\xd0\xb9 \xd0\xbf\xd0\xb8\xd0\xba \xd0\xb2\xd0\xbe\xd0\xbb\xd0\xbd\xd1\x8b \xd0\xbc\xd0\xb5\xd0\xb6\xd0\xb4\xd1\x83 \xd1\x81\xd1\x8d\xd0\xbc\xd0\xbf\xd0\xbb\xd0\xb0\xd0\xbc\xd0\xb8. \xd0\x95\xd1\x81\xd0\xbb\xd0\xb8 \xd0\xbe\xd0\xbd \xd0\xb2\xd1\x8b\xd1\x88\xd0\xb5 Ceiling, \xd0\xb7\xd0\xb2\xd1\x83\xd0\xba \xd0\xbc\xd0\xbe\xd0\xb6\xd0\xb5\xd1\x82 \xd0\xbf\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb3\xd1\x80\xd1\x83\xd0\xb7\xd0\xb8\xd1\x82\xd1\x8c\xd1\x81\xd1\x8f \xd0\xbf\xd0\xbe\xd1\x81\xd0\xbb\xd0\xb5 \xd0\xbf\xd0\xb5\xd1\x80\xd0\xb5\xd0\xb2\xd0\xbe\xd0\xb4\xd0\xb0 \xd0\xb2 MP3 \xd0\xb8 AAC. \xd0\x92\xd0\xba\xd0\xbb\xd1\x8e\xd1\x87\xd0\xb8\xd1\x82\xd0\xb5 Limiter.");
        out.push_back (c);
    }

    // Integrated loudness (information only)
    {
        Check c;
        c.light = Light::info;
        c.title = "Integrated";
        c.value = minus (in.integrated) + " LUFS";
        const double diff = in.integrated - t.integratedLufs;
        c.detail = (diff >= 0 ? "Louder than " : "Quieter than ") + minus (t.integratedLufs) + " (info only)";
        c.tooltip = ru ("\xd0\x98\xd0\xbd\xd1\x82\xd0\xb5\xd0\xb3\xd1\x80\xd0\xb0\xd0\xbb\xd1\x8c\xd0\xbd\xd0\xb0\xd1\x8f \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd0\xba\xd0\xbe\xd1\x81\xd1\x82\xd1\x8c \xd0\xb2\xd1\x81\xd0\xb5\xd0\xb3\xd0\xbe \xd1\x82\xd1\x80\xd0\xb5\xd0\xba\xd0\xb0. \xd0\xa6\xd0\xb5\xd0\xbb\xd1\x8c \xe2\x80\x94 \xd1\x82\xd0\xbe\xd0\xbb\xd1\x8c\xd0\xba\xd0\xbe \xd1\x81\xd0\xbf\xd1\x80\xd0\xb0\xd0\xb2\xd0\xba\xd0\xb0. \xd0\xa1\xd1\x82\xd1\x80\xd0\xb8\xd0\xbc\xd0\xb8\xd0\xbd\xd0\xb3\xd0\xbe\xd0\xb2\xd1\x8b\xd0\xb5 \xd1\x81\xd0\xb5\xd1\x80\xd0\xb2\xd0\xb8\xd1\x81\xd1\x8b \xd0\xb4\xd0\xb5\xd0\xbb\xd0\xb0\xd1\x8e\xd1\x82 \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd0\xba\xd0\xb8\xd0\xb5 \xd1\x82\xd1\x80\xd0\xb5\xd0\xba\xd0\xb8 \xd1\x82\xd0\xb8\xd1\x88\xd0\xb5. \xd0\xa1\xd0\xbe\xd0\xb2\xd1\x80\xd0\xb5\xd0\xbc\xd0\xb5\xd0\xbd\xd0\xbd\xd1\x8b\xd0\xb9 \xd0\xbc\xd0\xb5\xd1\x82\xd0\xb0\xd0\xbb \xd1\x87\xd0\xb0\xd1\x81\xd1\x82\xd0\xbe \xd0\xb3\xd1\x80\xd0\xbe\xd0\xbc\xd1\x87\xd0\xb5 \xd1\x8d\xd1\x82\xd0\xbe\xd0\xb9 \xd1\x86\xd0\xb5\xd0\xbb\xd0\xb8, \xd0\xb8 \xd1\x8d\xd1\x82\xd0\xbe \xd0\xbd\xd0\xbe\xd1\x80\xd0\xbc\xd0\xb0\xd0\xbb\xd1\x8c\xd0\xbd\xd0\xbe.");
        out.push_back (c);
    }
    return out;
}
} // namespace mm::analysis
